        return timeBucket; // No compression is applied for dayStep == 0
    }

    long compressedTimeBucket = 0;
    long dayBucketCount = timeBucket / dayStep; // Calculate the day step number required to form the compressedTimeBucket

    if (dayBucketCount > 0) {
        compressedTimeBucket = timeBucket - (dayBucketCount - 1) * dayStep; // Reset the time bucket to the start of the compressed day step
