final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    final int utfIndex = classFileBuffer.getInt(constantPoolEntryIndex * 2);
    int length = classFileBuffer.getByte(utfIndex++);
    if (length == 0x00) {
        // Handle zero-length strings
        return "";
    }
    int charsRead = 0;
    int charIndex = 0;
    if (length == 0x01 || length == 0x02 || length == 0x03) {
        // Handle Unicode characters without UTF-8 encoding
        final int charCount = length >> 1;
        for (int i = 0; i < charCount; i++) {
            int byte1 = classFileBuffer.getByte(utfIndex++);
            int byte2 = classFileBuffer.getByte(utfIndex++);
            charBuffer[charIndex++] = (char) ((byte1 << 8) | byte2);
            charsRead++;
        }
        return new String(charBuffer, 0, charsRead);
    } else if (length <= 0x7F) {
        // Handle plain ASCII strings
        final byte dataByte = classFileBuffer.getByte(utfIndex++);
        for (int i = 0; i < length; i++) {
            charBuffer[charIndex++] = dataByte;
            charsRead++;
        }
        return new String(charBuffer, 0, charsRead);
    } else {
        // Handle UTF-8 encoded strings
        int bits = 0;
        int charValue = 0;
        for (int i = 0; i < length; i++) {
            int byteValue = classFileBuffer.getByte(utfIndex++);
            bits |= byteValue & 0xFF;
            if ((bits & 0xC0) != 0x80) {
                // Single-byte character
                charValue = bits & 0x7F;
                break;
            }
            if ((bits & 0xE0) != 0xC0) {
                // Two-byte character
                charValue = ((bits & 0xF8) >> 2) | ((byteValue & 0x3F) << 6);
                break;
            }
            if ((bits & 0xF0) != 0xE0) {
                // Three-byte character
                charValue = ((bits & 0xFC) >> 4) | ((byteValue & 0x3F) << 2);
                break;
            }
            // Four-byte character (UTF-16 surrogate pair)
            charValue = ((bits & 0xFE) >> 6) |
                        ((byteValue & 0x3F) << 4) |
                        ((classFileBuffer.getByte(utfIndex++) & 0x3F) << 2) |
                        ((byteValue & 0x3F) << 0);
        }
        char[] chars = new char[(int) charValue];
        for (int i = 0; i < chars.length; i++) {
            charValue = (bits & 0xFC) >> 4) | ((byteValue & 0x3F) << 2);
            bits = (bits & 0xF8) >> 2) | ((byteValue & 0x3F) << 6);
            bytes = (bits & 0xC0) != 0x80 ? byteValue : classFileBuffer.getByte(utfIndex++);
            chars[i] = (char) ((bytes >> 8) | byteValue);
        }
        return new String(chars);
    }
}

